import{_ as a,o,c as t,a2 as s}from"./chunks/framework.lxr64Vqo.js";const m=JSON.parse('{"title":"Release v1.4.325","description":"","frontmatter":{},"headers":[],"relativePath":"updates/v1-4-325.md","filePath":"updates/v1-4-325.md","lastUpdated":1795114725000}'),n={name:"updates/v1-4-325.md"};function r(i,e,l,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="release-v1-4-325" tabindex="-1">Release v1.4.325 <a class="header-anchor" href="#release-v1-4-325" aria-label="Permalink to &quot;Release v1.4.325&quot;">​</a></h1><div style="margin-bottom:1.5rem;"><span class="badge-pill badge-feature">Feature</span><span class="badge-pill badge-perf">Performance</span><span style="color:#71717a;font-size:0.85rem;margin-left:8px;">Released on November 19, 2026</span></div><h2 id="infuse-vesper-custom-catalogs" tabindex="-1">Infuse &amp; Vesper Custom Catalogs <a class="header-anchor" href="#infuse-vesper-custom-catalogs" aria-label="Permalink to &quot;Infuse &amp; Vesper Custom Catalogs&quot;">​</a></h2><p>In this release, we introduce full support for <strong>Custom AI Shelves directly inside Infuse and Vesper</strong>.</p><p>Previously, Jellyfin bridge users could only browse default &quot;Movies&quot;, &quot;TV Shows&quot;, and &quot;Anime&quot; virtual folders. With v1.4.325, any custom catalog you create inside NoxMedia (such as <em>Murder Mystery Dark</em>, <em>Marvel Universe</em>, or <em>Retro Sci-Fi</em>) is dynamically exposed in the Jellyfin Bridge when Infuse or Vesper connects.</p><h3 id="pinned-favorites-on-apple-tv-ios" tabindex="-1">Pinned Favorites on Apple TV &amp; iOS <a class="header-anchor" href="#pinned-favorites-on-apple-tv-ios" aria-label="Permalink to &quot;Pinned Favorites on Apple TV &amp; iOS&quot;">​</a></h3><p>You can tap the <strong>Star</strong> icon on any custom shelf inside Infuse Files to pin it as a Home screen Favorite. It will render as a dedicated horizontal carousel on your Apple TV or iPhone/iPad.</p><hr><h2 id="zero-latency-instant-catalog-caching" tabindex="-1">Zero-Latency Instant Catalog Caching <a class="header-anchor" href="#zero-latency-instant-catalog-caching" aria-label="Permalink to &quot;Zero-Latency Instant Catalog Caching&quot;">​</a></h2><h3 id="problem-addressed" tabindex="-1">Problem Addressed <a class="header-anchor" href="#problem-addressed" aria-label="Permalink to &quot;Problem Addressed&quot;">​</a></h3><p>When Infuse opens a custom folder, it queries all items in that collection simultaneously. In earlier versions, this required parsing thousands of raw Telegram messages on the fly and performing synchronous HTTP network queries to resolve runtimes, resulting in a 1-2 minute delay.</p><h3 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><ul><li><strong>Precomputed In-Memory Cache</strong>: Media groups and catalog filters are precomputed in the background and stored in high-speed RAM and disk cache (<code>media_groups_cache.json</code>).</li><li><strong>Zero-Block HTTP Calls</strong>: Removed synchronous network lookups in <code>resolveRuntimeSeconds</code>, relying on pre-cached TMDB metadata and Telegram duration attributes.</li><li><strong>Result</strong>: Opening a custom shelf with hundreds of titles in Infuse and Vesper now loads with zero perceivable delay.</li></ul>',13)])])}const h=a(n,[["render",r]]);export{m as __pageData,h as default};
